class Solution {
public:
    int sumIndicesWithKSetBits(vector<int>& nums, int k) {
        int ans = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            int pc = __builtin_popcount(i);
            if (pc == k) ans += nums[i];
        }
        return ans;
    }
};

