class Solution:
    def sumIndicesWithKSetBits(self, nums: List[int], k: int) -> int:
        def pc(x):
            c = 0
            while x:
                x &= x - 1
                c += 1
            return c
        return sum(v for i, v in enumerate(nums) if pc(i) == k)

